INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q823730', 'First Sudanese Civil War', 'The First Sudanese Civil War (also known as the Anyanya Rebellion or Anyanya I, after the name of the rebels, a term in the Madi language which means ''snake venom'') was fought from 1955 to 1972 between the northern part of Sudan and the southern Sudan region which demanded representation and more regional autonomy. The war was divided into four major stages: initial guerrilla warfare, the creation of the Anyanya insurgency, political strife within the government, and establishment of the Southern Sudan Liberation Movement.', 1955, 8, 18, 1972, 3, 27, 'day', '18 August 1955 – 27 March 1972', 67, 'https://en.wikipedia.org/wiki/First_Sudanese_Civil_War'),
  ('Q303801', 'Lord''s Resistance Army insurgency', 'The Lord''s Resistance Army insurgency is an ongoing conflict between the Lord''s Resistance Army (LRA), a Ugandan militant religious extremist group, against the government of Uganda. Following the Ugandan Civil War, militant Joseph Kony formed the Lord''s Resistance Army and launched an insurgency against the newly installed President Yoweri Museveni.', 1987, NULL, NULL, NULL, NULL, NULL, 'year', '1987', 52, 'https://en.wikipedia.org/wiki/Lord''s_Resistance_Army_insurgency'),
  ('Q4871647', 'Battle of Malakal', 'The Battle of Malakal occurred at the end of November 2006 in the southern Sudanese town of Malakal. The clashes between Sudanese government forces and the Sudan People''s Liberation Army were the most serious breach of a 2005 deal to end the Second Sudanese Civil War.', 2006, 11, 27, 2006, 11, 29, 'day', '27 November 2006 – 29 November 2006', 37, 'https://en.wikipedia.org/wiki/Battle_of_Malakal'),
  ('Q223390', '2011 East Africa drought', 'Occurring between July 2011 and mid-2012, a severe drought affected the entire East African region. Said to be "the worst in 60 years", the drought caused a severe food crisis across Somalia, Djibouti, Ethiopia and Kenya that threatened the livelihood of 9.5 million people.', 2011, 7, NULL, 2012, 2, NULL, 'month', 'July 2011 – February 2012', 68, 'https://en.wikipedia.org/wiki/2011_East_Africa_drought'),
  ('Q28223405', 'Pibor massacre', 'The Pibor massacre occurred in Pibor County, South Sudan from 23 December 2011 to 4 January 2012. The fighting was between the Murle and the Lou Nuer, mostly over raiding cattle and abducting children to raise as their own.', 2011, 12, 23, 2012, 1, 4, 'day', '23 December 2011 – 4 January 2012', 34, 'https://en.wikipedia.org/wiki/Pibor_massacre'),
  ('Q15353665', 'South Sudanese Civil War', 'The South Sudanese Civil War was a multi-sided civil war in South Sudan fought from 2013 to 2018 between government and opposition forces. The civil war caused rampant human rights abuses, including forced displacement, ethnic massacres, and killings of journalists by various parties.', 2013, 12, 15, 2020, 2, 22, 'day', '15 December 2013 – 22 February 2020', 67, 'https://en.wikipedia.org/wiki/South_Sudanese_Civil_War'),
  ('Q16956086', 'Bentiu massacre', 'The Bentiu massacre occurred on 15 April 2014 in the town of Bentiu, in the north of South Sudan, during the South Sudanese Civil War. The attack was described by The Economist as the "worst massacre" of the civil war.', 2014, 4, 15, NULL, NULL, NULL, 'day', '15 April 2014', 41, 'https://en.wikipedia.org/wiki/Bentiu_massacre'),
  ('Q25753955', 'Battle of Juba', 'The Battle of Juba of 2016 was a series of clashes in South Sudan capital of Juba between rival factions of the Sudan People''s Liberation Army (SPLA) loyal to President Salva Kiir and Vice-President Riek Machar respectively.', 2016, 7, 7, 2016, 7, 11, 'day', '7 July 2016 – 11 July 2016', 37, 'https://en.wikipedia.org/wiki/Battle_of_Juba_(2016)'),
  ('Q28810727', '2017 South Sudan famine', 'Food insecurity has been a persistent and recurrent crisis in South Sudan since independence in 2011. Early conditions fluctuated between stressed and crisis levels, with localized emergencies along the Sudan border.', 2017, NULL, NULL, NULL, NULL, NULL, 'year', '2017', 50, 'https://en.wikipedia.org/wiki/Food_insecurity_and_famine_in_South_Sudan'),
  ('Q105947040', '2021 South Supreme Airlines Let L-410 Turbolet crash', 'On 2 March 2021, a Let L-410 Turbolet of South Sudan Supreme Airlines crashed in Pieri, Uror County, South Sudan on a domestic flight to Yuai Airstrip, South Sudan.', 2021, 3, 2, NULL, NULL, NULL, 'day', '2 March 2021', 50, 'https://en.wikipedia.org/wiki/2021_South_Sudan_Supreme_Airlines_Let_L-410_crash'),
  ('Q129317659', '2024 South Sudan floods', 'The 2024 South Sudan floods refer to catastrophic flooding across the African nation of South Sudan, resulting in "over 735,000 people across 38 of South Sudan’s 78 counties and the Abyei Administrative Area" being directly impacted, and 65,000 people being displaced, of which 41,000 were displaced from Warrap. Climate researchers theorized that altered climate patterns around the Sudd wetland region could result in the first mass-population displacement caused by climate change, due to the permanent expansion of uninhabitable wetlands caused by prolonged rainfall and flooding.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_South_Sudan_floods'),
  ('Q138011825', 'Jonglei clashes (2025–present)', 'Beginning in December 2025, and intensifying in 2026, clashes began between the Sudan People''s Liberation Movement-in-Opposition (SPLA-IO) and South Sudan People''s Defence Forces (SSPDF) within Jonglei State, South Sudan. The SPLA-IO launched an offensive in late December to capture several government strongholds within the majority Nuer Jonglei State in response to the continued imprisonment and treason trial of their leader Riek Machar after the 2025 Nasir clashes.', 2025, 12, 24, NULL, NULL, NULL, 'day', '24 December 2025', 34, 'https://en.wikipedia.org/wiki/Jonglei_clashes_(2025%E2%80%93present)');
